class Solution {
public:
    int best = 0;
    int arm(TreeNode* node) {
        if (!node) return 0;
        int l = arm(node->left);
        int r = arm(node->right);
        l = (node->left && node->left->val == node->val) ? l + 1 : 0;
        r = (node->right && node->right->val == node->val) ? r + 1 : 0;
        best = max(best, l + r);
        return max(l, r);
    }
    int longestUnivaluePath(TreeNode* root) {
        arm(root);
        return best;
    }
};
